import pathlib,json,re
rr=pathlib.Path("review/global-independent-review/seventh-2026-10-14-e646432-7a91");out=rr/"publication-staging/C21"
text=(rr/"handoff/cloud-seventh-update-handoff-prompt.md").read_text()
zh=json.loads((rr/"handoff/cloud-seventh-update-handoff-manifest.json").read_bytes())["complete_chinese_contracts"]
heads=re.findall(r"(?m)^#{1,6}[^\n]*",text)
