fences=[]
for b in re.findall(r"```json[^\n]*\n(.*?)\n```",text,re.S):
 try:fences.append(json.loads(b))
 except ValueError:pass
print("FENCE_COUNTS",len(fences))
print("FIRST_FENCE_KEYS",[list(x) if isinstance(x,dict) else type(x).__name__ for x in fences[:5]])
found={}
for r in zh["records"]:
 found[r["id"]]={k:any(x==v for x in fences) for k,v in r["groups"].items()}
print("INDIVIDUAL_GROUPS_PRESENT",json.dumps({"records":len(found),"groups":sum(len(x) for x in found.values()),"missing":{k:[g for g,ok in v.items() if not ok] for k,v in found.items() if not all(v.values())}},ensure_ascii=False))
